+      color: var(--error);
+      font-weight: 700;
+    }
+
+    .success-message {
+      color: var(--success);
+      font-weight: 700;
+    }
+
+    button {
+      min-height: 3.35rem;
+      margin-top: 0.3rem;
+      border: 0;
+      border-radius: 999px;
+      color: white;
+      background: linear-gradient(135deg, var(--accent), #0ea5e9);
+      box-shadow: 0 1rem 2rem rgba(14, 165, 233, 0.22);
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      letter-spacing: 0.01em;
+      transition: transform 160ms ease, box-shadow 160ms ease;
+    }
+
+    button:hover {
+      transform: translateY(-1px);
