  <main id="root"></main>

  <script>
    const fields = [
      {
        id: "fullName",
        name: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        placeholder: "Jane Doe",
        required: true
      },
      {
        id: "email",
        name: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        placeholder: "jane@example.com",
        required: true
      },
      {
        id: "phone",
        name: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        placeholder: "+1 555 123 4567",
        required: false,
        helperText: "Optional. Use digits, spaces, dashes, parentheses, or a leading plus sign, such as +1 555 123 4567."
      }
    ];

    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {},
      submitted: false,
      success: false
    };

    function validateField(name, value) {
      const trimmedValue = value.trim();

      if (name === "fullName" && !trimmedValue) {
        return "Full name is required.";
      }

      if (name === "email") {
        if (!trimmedValue) {
          return "Email address is required.";
        }

        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)) {
          return "Enter a valid email address, such as jane@example.com.";
        }
      }

      if (name === "phone" && trimmedValue && !/^\+?[0-9\s().-]{7,20}$/.test(trimmedValue)) {
        return "Enter a valid phone number using 7 to 20 digits and common separators.";
      }

      return "";
    }

    function escapeAttribute(value) {
      return value
        .replace(/&/g, "&amp;")
        .replace(/"/g, "&quot;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
    }

    function getErrors() {
      return fields.reduce((errors, field) => {
        errors[field.name] = validateField(field.name, state.values[field.name]);
        return errors;
      }, {});
    }

    function FormField({ field, error, showError }) {
      const helperId = field.helperText ? `${field.id}-helper` : "";
      const errorId = `${field.id}-error`;
      const describedBy = [helperId, showError ? errorId : ""].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${field.required ? " *" : ""}</label>
          <input
            id="${field.id}"
            name="${field.name}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            placeholder="${field.placeholder}"
            value="${escapeAttribute(state.values[field.name])}"
            ${field.required ? "required" : ""}
            aria-invalid="${showError ? "true" : "false"}"
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
          >
          ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
          ${showError ? `<p class="error-message" id="${errorId}">${error}</p>` : ""}
        </div>
      `;
    }

    function SupportContactForm() {
      const errors = getErrors();
      const hasErrors = Object.values(errors).some(Boolean);

      return `
        <section class="support-card" aria-labelledby="support-title">
          <p class="eyebrow">Support request</p>
          <h1 id="support-title">Contact our support team</h1>
          <p class="intro">Tell us how to reach you and our team will follow up with next steps.</p>
          <form novalidate>
            ${fields.map((field) => FormField({
              field,
              error: errors[field.name],
              showError: Boolean(errors[field.name] && (state.touched[field.name] || state.submitted))
            })).join("")}
            <button type="submit">Submit support request</button>
            ${state.success && !hasErrors ? '<p class="success-message" role="status">Thanks. Your support request is ready to send.</p>' : ""}
          </form>
        </section>
      `;
    }

    function render() {
      document.getElementById("root").innerHTML = SupportContactForm();
      attachFormHandlers();
    }

    function attachFormHandlers() {
      const form = document.querySelector("form");

      fields.forEach((field) => {
        const input = document.getElementById(field.id);

        input.addEventListener("input", (event) => {
          state.values[field.name] = event.target.value;
          state.success = false;
          render();
          document.getElementById(field.id).focus();
        });

        input.addEventListener("blur", () => {
          state.touched[field.name] = true;
          render();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;
        state.touched = fields.reduce((touched, field) => {
          touched[field.name] = true;
          return touched;
        }, {});
        state.success = !Object.values(getErrors()).some(Boolean);
